#!/usr/bin/env python3
"""Generate tables directly from archived paired measurements."""
import argparse
import json
import statistics
from pathlib import Path


def pct(ratio):
    return f'{(ratio - 1) * 100:+.2f}%'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('directory', type=Path)
    args = parser.parse_args()
    root = args.directory
    sections = ['# Optional writing performance experiment', '',
                'Generated by `benchmarks/optional-writing/report.py`. Ratios compare elapsed time; positive percentages mean slower. Medians across rows are descriptive, unweighted summaries, not workload-frequency estimates.', '']
    for name in ['gfm', 'confirmation', 'commonmark', 'outlier']:
        if not (root / name / 'summary.json').exists():
            continue
        data = json.loads((root / name / 'summary.json').read_text())
        run = json.loads((root / name / 'run.json').read_text())
        sections += [f'## {name}', '', f'{len(data)} comparisons, {run["pairs"]} alternating pairs per comparison, {run["window_ms"]} ms per side. All three entry-point lifecycles are retained in the raw data.', '',
                     '| Comparison / workload | Rows | Median change | Row median range |',
                     '| --- | ---: | ---: | ---: |']
        groups = [('baseline', 'All inputs', None),
                  ('highlight', 'Unused: project documents, prose, mixed Markdown', ['document', 'prose', 'mixed']),
                  ('notes', 'Unused: project documents, prose, mixed Markdown', ['document', 'prose', 'mixed']),
                  ('both', 'Unused: project documents, prose, mixed Markdown', ['document', 'prose', 'mixed']),
                  ('both', 'Unused: literal equals/carets', ['equals-caret']),
                  ('both', 'Malformed markers', ['malformed']),
                  ('both', 'One mark and one note per document', ['sparse-active']),
                  ('highlight', 'Dense marks (different HTML)', ['highlight-active']),
                  ('notes', 'Dense notes (different HTML)', ['notes-active']),
                  ('no-refs', 'No definitions: prose and mixed Markdown', ['prose', 'mixed']),
                  ('no-refs', 'Reference-heavy (different HTML)', ['reference-active'])]
        for comparison, label, kinds in groups:
            rows = [r for r in data if r['comparison'] == comparison and (kinds is None or r['kind'] in kinds)]
            if not rows: continue
            values = [r['ratio'] for r in rows]
            sections.append(f'| {comparison}: {label} | {len(rows)} | {pct(statistics.median(values))} | {pct(min(values))} to {pct(max(values))} |')
        sections += ['', '### Baseline comparison by lifecycle', '',
                     '| Lifecycle | Median change | Row median range |', '| --- | ---: | ---: |']
        for stage in ['parse', 'reuse', 'fresh']:
            values = [r['ratio'] for r in data if r['comparison'] == 'baseline' and r['stage'] == stage]
            if values: sections.append(f'| {stage} | {pct(statistics.median(values))} | {pct(min(values))} to {pct(max(values))} |')
        sections += ['', f'[Full row summaries]({name}/summary.json), [raw timings and verified output]({name}/results.json.gz), [build identities]({name}/builds.json).', '']
    (root / 'tables.md').write_text('\n'.join(sections))

if __name__ == '__main__':
    main()
